sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   var user = g_form.getValue('employee');
    if (user == '') {
        g_form.addErrorMessage('Please select an employee first.');
        return;
    }

    // Call the Script Include
    var ga = new GlideAjax('LeaveBalanceAjax');
    ga.addParam('sysparm_name', 'getBalance');
    ga.addParam('sysparm_user', user);
    ga.addParam('sysparm_leave_type', newValue);

    // Process the asynchronous response
    ga.getXMLAnswer(function(response) {
        var balance = parseInt(response, 10);

        // Display the fetched balance on the form
        g_form.setValue('leave_balance_at_request', balance);
        g_form.showFieldMsg('leave_balance_at_request', 'Current balance for ' + newValue + ' leave is ' + balance + ' days.', 'info');
    });

}
